package com.nexodb.db;

import javax.net.ssl.SSLSocketFactory;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;

/** Minimal native Redis RESP2 client for safe inspection; no third-party driver is required. */
public final class RedisNativeClient implements AutoCloseable {
 public record Key(String name,String type,long ttl,String preview){}
 private final Socket socket;private final InputStream input;private final OutputStream output;
 public RedisNativeClient(String host,int port,boolean tls,String user,char[] password)throws Exception{socket=tls?SSLSocketFactory.getDefault().createSocket():new Socket();socket.connect(new InetSocketAddress(host,port),7000);socket.setSoTimeout(10000);input=socket.getInputStream();output=socket.getOutputStream();if(password!=null&&password.length>0){Object reply=call(user==null||user.isBlank()?new String[]{"AUTH",new String(password)}:new String[]{"AUTH",user,new String(password)});if(!"OK".equalsIgnoreCase(Objects.toString(reply,"")))throw new IOException("Redis rechazó la autenticación.");}}
 public String ping()throws Exception{return Objects.toString(call("PING"),"");}
 public List<Key> scan(int maximum)throws Exception{List<Key> result=new ArrayList<>();String cursor="0";do{Object response=call("SCAN",cursor,"COUNT",Integer.toString(Math.min(1000,Math.max(20,maximum))));if(!(response instanceof List<?> parts)||parts.size()<2)throw new IOException("Respuesta SCAN no válida.");cursor=Objects.toString(parts.get(0),"0");if(parts.get(1) instanceof List<?> keys)for(Object item:keys){if(result.size()>=maximum)break;String key=Objects.toString(item,"");String type=Objects.toString(call("TYPE",key),""),preview=preview(key,type);long ttl=Long.parseLong(Objects.toString(call("TTL",key),"-1"));result.add(new Key(key,type,ttl,preview));}}while(!cursor.equals("0")&&result.size()<maximum);return List.copyOf(result);}
 private String preview(String key,String type)throws Exception{Object value=switch(type){case "string"->call("GET",key);case "hash"->call("HLEN",key);case "list"->call("LLEN",key);case "set"->call("SCARD",key);case "zset"->call("ZCARD",key);case "stream"->call("XLEN",key);default->"";};String text=Objects.toString(value,"");if(!type.equals("string")&&!text.isBlank())text=text+" elemento(s)";return text.length()>500?text.substring(0,499)+"…":text;}
 public synchronized Object call(String...parts)throws Exception{output.write(command(parts));output.flush();return read();}
 public static byte[] command(String...parts)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(("*"+parts.length+"\r\n").getBytes(StandardCharsets.UTF_8));for(String part:parts){byte[] value=part.getBytes(StandardCharsets.UTF_8);out.write(("$"+value.length+"\r\n").getBytes(StandardCharsets.UTF_8));out.write(value);out.write("\r\n".getBytes(StandardCharsets.UTF_8));}return out.toByteArray();}
 private Object read()throws Exception{int marker=input.read();if(marker<0)throw new EOFException("Redis cerró la conexión.");String line=readLine();return switch(marker){case '+'->line;case '-'->throw new IOException("Redis: "+line);case ':'->Long.parseLong(line);case '$'->{int length=Integer.parseInt(line);if(length<0)yield null;byte[] value=input.readNBytes(length);if(value.length!=length)throw new EOFException();expectCrLf();yield new String(value,StandardCharsets.UTF_8);}case '*'->{int count=Integer.parseInt(line);if(count<0)yield null;List<Object> values=new ArrayList<>(count);for(int i=0;i<count;i++)values.add(read());yield values;}default->throw new IOException("Respuesta RESP desconocida: "+(char)marker);};}
 private String readLine()throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();int previous=-1;while(true){int value=input.read();if(value<0)throw new EOFException();if(previous=='\r'&&value=='\n'){byte[] data=out.toByteArray();return new String(data,0,Math.max(0,data.length-1),StandardCharsets.UTF_8);}out.write(value);previous=value;}}
 private void expectCrLf()throws IOException{if(input.read()!='\r'||input.read()!='\n')throw new IOException("Respuesta RESP incompleta.");}
 public void close(){try{socket.close();}catch(IOException ignored){}}
}
